{"version":3,"sources":["..\\scss\\helpPage.scss","helpPage.css","..\\scss\\_mixins.scss","..\\scss\\_variables.scss"],"names":[],"mappings":"AAIA;EACE,6BAAA;EACA,iBAAA;ACHF;ADIE;EENE,uCAAA;EACA,gBFMoC;EELpC,kBAAA;EACA,YCHW;EDIX,eFG8B;ACElC;ADCE;EACE,aAAA;EACA,sBAAA;EACA,SAAA;ACCJ;ADEE;EACE,kBAAA;ACAJ","file":"helpPage.css","sourcesContent":["@import \"./variables\";\r\n@import \"./mixins\";\r\n\r\n\r\n.help {\r\n  border-top: 1px solid $gray;\r\n  padding-top: 15px;\r\n  & p,li {\r\n    @include fonts($defaultColor, 15px, 400)\r\n  }\r\n\r\n  ul, ol {\r\n    display: flex;\r\n    flex-direction: column;\r\n    gap: 10px;\r\n  }\r\n\r\n  li {\r\n    padding-left: 10px;\r\n  }\r\n}",".help {\n  border-top: 1px solid #D4D4D4;\n  padding-top: 15px;\n}\n.help p, .help li {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 15px;\n}\n.help ul, .help ol {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n.help li {\n  padding-left: 10px;\n}","@mixin fonts($color,$size,$weight) {\r\n    font-family: 'Trebuchet MS', sans-serif;\r\n    font-weight: $weight;\r\n    font-style: normal;\r\n    color: $color;\r\n    font-size: $size;\r\n}","$mainColor: #3077a0;\r\n$defaultColor: black;\r\n$colorHover: red;\r\n$headerTopBorder: #bdd4e2;\r\n$buttonBg:linear-gradient(0deg, #4d95d6,#6e93dd,#c2d6f4);;\r\n$gray: #D4D4D4;\r\n$vipBg: #ff6163;\r\n$activeItem: #FFFFCA;\r\n$userSearchBg: #CFE6FE;\r\n$asideLinksColor: #307792;\r\n$asideExitColor: rgb(0, 128, 0);"]} #307792;\r\n$asideExitColor: rgb(0, 128, 0);"]}